//! Replays the Node oracle sets in `tests/fixtures/rust-core/lua` (generated by
//! `benchmarks/rust-core-oracles/lua-edit.oracle.test.ts`).
use super::access::{AccessPool, Exposure, FinishMode, Limits as StoreLimits, OwnerPermit, ScriptStoreAccess};
use super::lua_edit::{answer, copy_value, edit_effects, ir_limits, wrapper, Batch, Context, Edit, EditHost, EditMode, Gate, Status, EDIT_API, HOST_API};
use super::lua_scalar_adapter::SCALAR_API;
use crate::persistent_store::{script_access::Target, PersistentStore};
use risunest_ir::chat::{MessageRole, PromptMessage};
use risunest_ir::stage::{Effect, HostReply, HostRequest, LuaMode, LuaReply, LuaTrigger, MessageEdit, ScriptMode};
use risunest_ir::{json, num, Budget, Text, Value};
use risunest_native_lua_experimental::{js_string_bytes, Cancellation, Limits};
use risunest_records::edits::edit_messages;
use serde_json::{json, Value as Json};
use sha2::{Digest, Sha256};
use std::{cell::RefCell, rc::Rc, sync::{atomic::AtomicBool, Arc}, time::Duration};

macro_rules! oracle_set {
    ($set:literal) => {
        load($set,
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../tests/fixtures/rust-core/lua/", $set, ".cases.json")),
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../tests/fixtures/rust-core/lua/", $set, ".expected.json")))
    };
}

fn hex(bytes: &[u8]) -> String { bytes.iter().map(|byte| format!("{byte:02x}")).collect() }

// Each case paired with its expected result, after the header checks every replay shares.
fn load(set: &str, cases: &[u8], expected: &[u8]) -> Vec<(Json, Json)> {
    let expected: Json = serde_json::from_slice(expected).unwrap();
    assert_eq!(expected["fixtureSha256"].as_str(), Some(hex(&Sha256::digest(cases)).as_str()), "{set}: the expected file is stale");
    let cases: Json = serde_json::from_slice(cases).unwrap();
    let (cases, results) = (cases["cases"].as_array().unwrap(), expected["cases"].as_array().unwrap());
    assert!(!cases.is_empty(), "{set}: no cases");
    assert_eq!(cases.len(), results.len(), "{set}: case count");
    cases.iter().zip(results).map(|(case, result)| {
        assert_eq!(case["id"], result["id"], "{set}: case order");
        (case.clone(), result["result"].clone())
    }).collect()
}

fn check(set: &str, pairs: &[(Json, Json)], mut matches: impl FnMut(&Json, &Json) -> Result<(), String>) {
    let mismatches = pairs.iter().filter_map(|(case, expected)| matches(case, expected).err().map(|reason| format!("{}: {reason}", case["id"])))
        .collect::<Vec<_>>();
    println!("{set}: {} cases, {} mismatches", pairs.len(), mismatches.len());
    assert!(mismatches.is_empty(), "{set}: {} of {} cases differ:\n{}", mismatches.len(), pairs.len(), mismatches.join("\n"));
}

fn units(text: &Json) -> Vec<u16> {
    match text {
        Json::String(value) => value.encode_utf16().collect(),
        _ => text["u"].as_array().unwrap().iter().map(|unit| unit.as_u64().unwrap() as u16).collect(),
    }
}

fn budget() -> Budget { Budget::new(ir_limits(), Arc::new(AtomicBool::new(false))).unwrap() }

// The oracle's `tag`: JS strings as text or units, numbers as `String(value)`, object keys sorted by UTF-16 units.
fn text_json(text: &Text) -> Json {
    text.as_unicode().map_or_else(|| json!({ "u": text.units().collect::<Vec<_>>() }), Json::from)
}
fn number_json(value: f64, budget: &Budget) -> Json {
    if value == 0.0 && value.is_sign_negative() { return json!(["number", "-0"]); }
    json!(["number", num::number_to_text(value, budget).unwrap().as_unicode().unwrap()])
}
fn tag(value: &Value, budget: &Budget) -> Json {
    match value {
        Value::Undefined => json!(["undefined"]),
        Value::Null => json!(["null"]),
        Value::Bool(value) => json!(["bool", value]),
        Value::Number(value) => number_json(*value, budget),
        Value::Text(text) => json!(["string", text_json(text)]),
        Value::Array(items) => json!(["array", items.as_slice().iter().map(|item| tag(item, budget)).collect::<Vec<_>>()]),
        Value::Object(entries) => {
            let mut entries = entries.as_slice().iter().collect::<Vec<_>>();
            entries.sort_by(|left, right| left.0.units().cmp(right.0.units()));
            json!(["object", entries.iter().map(|(key, item)| json!([text_json(key), tag(item, budget)])).collect::<Vec<_>>()])
        }
    }
}
fn stored_tag(value: &Json, budget: &Budget) -> Json {
    match value {
        Json::Null => json!(["null"]),
        Json::Bool(value) => json!(["bool", value]),
        Json::Number(value) => number_json(value.as_f64().unwrap(), budget),
        Json::String(value) => json!(["string", value]),
        Json::Array(items) => json!(["array", items.iter().map(|item| stored_tag(item, budget)).collect::<Vec<_>>()]),
        Json::Object(entries) => {
            let mut entries = entries.iter().collect::<Vec<_>>();
            entries.sort_by(|left, right| left.0.encode_utf16().cmp(right.0.encode_utf16()));
            json!(["object", entries.iter().map(|(key, item)| json!([key, stored_tag(item, budget)])).collect::<Vec<_>>()])
        }
    }
}

// The oracle's `uuid` pattern.
fn is_uuid_v4(id: &str) -> bool {
    id.len() == 36 && id.bytes().enumerate().all(|(index, byte)| match index {
        8 | 13 | 18 | 23 => byte == b'-',
        14 => byte == b'4',
        19 => matches!(byte, b'8' | b'9' | b'a' | b'b'),
        _ => byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte),
    })
}
// The oracle's `storedMessage`, with `ids` the case rows' `chatId` (`None` where a row has none).
fn stored_message(row: &Json, ids: &[Option<Json>], budget: &Budget) -> Json {
    let id = row.get("chatId");
    let id_tag = if ids.contains(&id.cloned()) { json!(["kept", id]) }
        else if id.and_then(Json::as_str).is_some_and(is_uuid_v4) { json!(["new"]) }
        else { json!(["other", id.map_or_else(|| json!(["undefined"]), |id| stored_tag(id, budget))]) };
    let mut extra = row.as_object().unwrap().iter().filter(|(key, _)| !["role", "data", "chatId"].contains(&key.as_str())).collect::<Vec<_>>();
    extra.sort_by(|left, right| left.0.encode_utf16().cmp(right.0.encode_utf16()));
    json!([stored_tag(&row["role"], budget), stored_tag(&row["data"], budget), id_tag,
        extra.iter().map(|(key, value)| json!([key, stored_tag(value, budget)])).collect::<Vec<_>>()])
}

// The oracle's `canonicalRequest`, through the PromptMessage conversion the prompt stage reads the reply with.
const PROMPT_FIELDS: [&str; 9] = ["role", "content", "name", "memo", "attr", "multimodals", "thoughts", "removable", "cachePoint"];
fn canonical_request(value: &Value, budget: &Budget) -> Result<Json, String> {
    let Value::Array(items) = value else { return Ok(tag(value, budget)) };
    let mut messages = Vec::new();
    for item in items.as_slice() {
        if !matches!(item, Value::Object(_)) { messages.push(tag(item, budget)); continue; }
        let message = PromptMessage::from_value(copy_value(item, budget).unwrap(), budget).map_err(|error| format!("prompt message: {error:?}"))?;
        let Value::Object(entries) = message.to_value(budget).unwrap() else { unreachable!() };
        let field = |key: &Text| PROMPT_FIELDS.iter().any(|name| key.equals_ascii(name.as_bytes()));
        let mut extra = entries.as_slice().iter().filter(|(key, _)| !field(key)).collect::<Vec<_>>();
        extra.sort_by(|left, right| left.0.units().cmp(right.0.units()));
        let known = entries.as_slice().iter().filter(|(key, _)| field(key));
        messages.push(json!(["object", known.chain(extra).map(|(key, item)| json!([text_json(key), tag(item, budget)])).collect::<Vec<_>>()]));
    }
    Ok(json!(["array", messages]))
}

fn settings() -> StoreLimits {
    StoreLimits { active_scopes: 4, aggregate_bytes: 4_000_000, scope_bytes: 1_000_000,
        variable_bytes: 100_000, variable_count: 128, staged_bytes: 100_000, staged_rows: 128,
        read_page_rows: 1, read_page_bytes: 100_000, result_bytes: 200_000,
        waits: 8, receipts: 16, receipt_bytes: 100_000, commit_attempts: 3, lifetime: Duration::from_secs(3600) }
}
fn fixture(rows: &Json, scriptstate: &Json) -> (tempfile::TempDir, Rc<RefCell<PersistentStore>>) {
    let directory = tempfile::tempdir().unwrap();
    let mut store = PersistentStore::open(directory.path()).unwrap();
    let mut database: Json = serde_json::from_str(include_str!("../../fixtures/persistent-fixture.json")).unwrap();
    database["characters"][0]["chats"][0]["message"] = rows.clone();
    database["characters"][0]["chats"][0]["scriptstate"] = scriptstate.clone();
    let characters = database.as_object_mut().unwrap().remove("characters").unwrap();
    let presets = database.as_object_mut().unwrap().remove("botPresets").unwrap();
    let stage = store.replace_begin().unwrap();
    store.replace_put_root(&stage.staging_id, &database).unwrap();
    store.replace_put_presets(&stage.staging_id, presets.as_array().unwrap()).unwrap();
    store.replace_add_characters(&stage.staging_id, characters.as_array().unwrap()).unwrap();
    store.replace_commit(&stage.staging_id, Some(store.revision().unwrap())).unwrap();
    (directory, Rc::new(RefCell::new(store)))
}
fn scope(store: &Rc<RefCell<PersistentStore>>, pool: &AccessPool) -> Rc<ScriptStoreAccess> { exposed(store, pool, Exposure::Full) }
fn exposed(store: &Rc<RefCell<PersistentStore>>, pool: &AccessPool, exposure: Exposure) -> Rc<ScriptStoreAccess> {
    let store = store.borrow();
    let target = Target { character_id: "char-b".into(), conversation_id: "conv-beta".into(),
        library_identity: store.library_identity().unwrap(), binding_authority: store.lww_binding_authority().unwrap() };
    Rc::new(ScriptStoreAccess::open(&store, target, store.revision().unwrap(), OwnerPermit::new(), exposure, pool).unwrap())
}
// `commitIfChanged`, which TS runs after every batch.
fn commit(access: &ScriptStoreAccess, store: &Rc<RefCell<PersistentStore>>) {
    let outcome = access.commit(&mut store.borrow_mut(), &access.next_segment().unwrap(), FinishMode::IfChanged).unwrap();
    assert_eq!(outcome.error, None);
}
fn conversation(store: &Rc<RefCell<PersistentStore>>) -> Json {
    store.borrow().read_conversation("char-b", "conv-beta", None).unwrap().unwrap().value
}
fn host_with(capacity: usize) -> EditHost {
    EditHost::new(Limits { instructions_per_slice: 100_000, ..Limits::default() }, Duration::from_secs(5), capacity).unwrap()
}
// The normal runtime profile's `scriptingEngineCacheEntries`.
fn host() -> EditHost { host_with(16) }

fn mode(name: &str) -> Option<EditMode> {
    match name {
        "editinput" => Some(EditMode::Input), "editoutput" => Some(EditMode::Output), "editdisplay" => Some(EditMode::Display),
        "editRequest" => Some(EditMode::Request), "editprocess" => None,
        _ => panic!("unknown edit mode {name}"),
    }
}
fn content(case: &Json, budget: &Budget) -> Value {
    if case["mode"] == "editRequest" { json::parse_json(&case["data"].to_string(), budget).unwrap() }
    else { Value::Text(Text::from_units(&units(&case["data"]), budget).unwrap()) }
}
fn codes(case: &Json) -> Vec<String> {
    case["triggers"].as_array().unwrap().iter().chain(case["modules"].as_array().unwrap()).map(|code| code.as_str().unwrap().to_owned()).collect()
}

#[test]
fn wasmoon_receives_js_strings_with_the_pinned_encoder() {
    check("encode", &oracle_set!("encode"), |case, expected| {
        let actual = js_string_bytes(&units(&case["text"])).into_iter().map(Json::from).collect::<Vec<_>>();
        if Json::Array(actual.clone()) == *expected { Ok(()) } else { Err(format!("{actual:?}, expected {expected}")) }
    });
}

#[test]
fn the_wrapper_is_lua_code_wrapper_of_empty_code() {
    let (prefix, suffix) = wrapper().unwrap();
    let digest = hex(&Sha256::digest(format!("{prefix}{suffix}").as_bytes()));
    check("wrapper", &oracle_set!("wrapper"), |_, expected| {
        if expected.as_str() == Some(digest.as_str()) { Ok(()) } else { Err(format!("{digest}, expected {expected}")) }
    });
}

#[test]
fn edit_batches_match_main_thread_wasmoon() {
    check("edit", &oracle_set!("edit"), |case, expected| {
        let budget = budget();
        let (_directory, store) = fixture(&case["rows"], &case["scriptstate"]);
        let pool = AccessPool::new(settings()).unwrap();
        let mut host = host();
        let triggers = codes(case);
        let index = case["index"].as_i64();
        let ids = case["rows"].as_array().unwrap().iter().map(|row| row.get("chatId").cloned()).collect::<Vec<_>>();
        let mut calls = Vec::new();
        for _ in 0..case["calls"].as_u64().unwrap() {
            let access = scope(&store, &pool);
            let before = conversation(&store)["message"].clone();
            let mut edits = Vec::new();
            let data = match mode(case["mode"].as_str().unwrap()) {
                None => match answer(&mut host, HostRequest::Lua { trigger: LuaTrigger::Edit { index }, mode: LuaMode::Script(ScriptMode::EditProcess),
                    payload: content(case, &budget) }, Context { owner: "char-b", triggers: &triggers, access: &access, store: &store,
                    cancellation: &Cancellation::default(), budget: &budget }).map_err(|failure| format!("{failure:?}"))? {
                    HostReply::Lua(LuaReply { value, effects, stop_sending: false }) if effects.is_empty() => value,
                    reply => return Err(format!("editprocess reply {reply:?}")),
                },
                Some(mode) => {
                    let outcome = host.run(Batch { owner: "char-b", mode, content: content(case, &budget), index, triggers: &triggers,
                        access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).map_err(|failure| format!("{failure:?}"))?;
                    commit(&access, &store);
                    match (case["decline"].as_str(), outcome.status) {
                        (Some(label), Status::Declined(actual)) if actual == label => return Ok(()),
                        (None, Status::Completed) => { edits = outcome.edits; outcome.value }
                        (label, status) => return Err(format!("status {status:?}, expected {label:?}")),
                    }
                }
            };
            drop(access);
            let stored = conversation(&store);
            // The reported effects turn the rows the call started from into the stored rows.
            let mut replayed = json::parse_json(&before.to_string(), &budget).unwrap();
            for effect in edit_effects(&edits, &budget).map_err(|error| format!("effects: {error:?}"))? {
                let Effect::Message(edit) = effect else { continue };
                edit_messages(&mut replayed, &edit, &budget).map_err(|error| format!("effect {edit:?}: {error:?}"))?;
            }
            let (replayed, rows) = (tag(&replayed, &budget), tag(&json::parse_json(&stored["message"].to_string(), &budget).unwrap(), &budget));
            if replayed != rows { return Err(format!("\n  effects give {replayed}\n  stored       {rows}")); }
            let mut state = stored["scriptstate"].as_object().unwrap().iter().collect::<Vec<_>>();
            state.sort_by(|left, right| left.0.encode_utf16().cmp(right.0.encode_utf16()));
            calls.push(json!({
                "data": if case["mode"] == "editRequest" { canonical_request(&data, &budget)? } else { tag(&data, &budget) },
                "scriptstate": state.iter().map(|(key, value)| json!([key, stored_tag(value, &budget)])).collect::<Vec<_>>(),
                "messages": stored["message"].as_array().unwrap().iter().map(|row| stored_message(row, &ids, &budget)).collect::<Vec<_>>(),
            }));
        }
        let actual = json!({ "calls": calls });
        if actual == *expected { Ok(()) } else { Err(format!("\n  actual   {actual}\n  expected {expected}")) }
    });
}

// The gate of each host name follows the check its `scriptings.ts` declaration starts with.
#[test]
fn the_host_table_follows_every_lua_declaration() {
    let source = include_str!("../../../src/ts/process/scriptings.ts").replace("\r\n", "\n");
    let mut declared: Vec<(&str, bool, &str)> = Vec::new();
    for piece in source.split("declareAPI('").skip(1) {
        let name = &piece[..piece.find('\'').unwrap()];
        // The declaration line and the statements before its first check.
        let head = piece[name.len()..].lines().take(7).collect::<Vec<_>>().join("\n");
        let asynchronous = head.trim_start_matches(['\'', ',', ' ']).starts_with("async ");
        let check = if head.contains("if(!ScriptingSafeIds.has(id) && !ScriptingEditDisplayIds.has(id))") { "safe-or-display" }
            else if head.contains("if(!ScriptingSafeIds.has(id))") { "safe" }
            else if head.contains("if(!ScriptingLowLevelIds.has(id))") && head.contains("JSON.parse(promptStr)") { "parsed-low-level" }
            else if head.contains("if(!ScriptingLowLevelIds.has(id))") { "low-level" }
            else { "none" };
        // A later declaration replaces the global; both must agree.
        match declared.iter().find(|entry| entry.0 == name) {
            Some(entry) => assert_eq!(*entry, (name, asynchronous, check), "redeclared {name}"),
            None => declared.push((name, asynchronous, check)),
        }
    }
    let served = SCALAR_API.iter().copied().chain(EDIT_API).chain(["getChatMain", "getRecentChatsMain", "getFullChatMain"]).collect::<Vec<_>>();
    let expected = HOST_API.iter().map(|(name, asynchronous, gate)| (*name, *asynchronous, match gate {
        Gate::Served if ["setChatVar", "setChatVarChanged"].contains(name) => "safe-or-display",
        Gate::Served if ["setChat", "setChatRole"].contains(name) || EDIT_API.contains(name) => "safe",
        Gate::Served | Gate::Always | Gate::Log => "none",
        Gate::Safe | Gate::Ignored => "safe",
        Gate::LowLevel => "low-level",
        Gate::ParsedPrompt => "parsed-low-level",
    })).collect::<Vec<_>>();
    assert_eq!(declared, expected);
    let mut table_served = HOST_API.iter().filter(|entry| entry.2 == Gate::Served).map(|entry| entry.0).collect::<Vec<_>>();
    let mut served = served;
    table_served.sort_unstable();
    served.sort_unstable();
    assert_eq!(table_served, served);
}

// A windowed history (`toHistorySpliceIndex`) is not modeled: each structural write declines and the rows stay.
#[test]
fn structural_edits_decline_on_a_windowed_history() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "a", "chatId": "m1" }, { "role": "char", "data": "b", "chatId": "m2" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = exposed(&store, &pool, Exposure::Window { start: 1, length: 1 });
    let mut host = host();
    for (name, call) in [("removeChat", "removeChat(id, 0)"), ("insertChat", "insertChat(id, 0, 'user', 'x')"), ("setFullChatMain", "setFullChatMain(id, '[]')")] {
        let triggers = [format!("listenEdit('editOutput', function(id, value) {call} return value end)")];
        let outcome = host.run(Batch { owner: "char-b", mode: EditMode::Output, content: Value::Text(Text::from_str("v", &budget).unwrap()), index: Some(0),
            triggers: &triggers, access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).unwrap();
        assert_eq!(outcome.status, Status::Declined(format!("lua-host-error:{name}")));
        assert!(outcome.edits.is_empty(), "{:?}", outcome.edits);
    }
    commit(&access, &store);
    let stored = conversation(&store)["message"].as_array().unwrap().iter().map(|row| row["data"].clone()).collect::<Vec<_>>();
    assert_eq!(stored, ["a", "b"]);
}

fn request(mode: LuaMode, payload: Value) -> HostRequest { HostRequest::Lua { trigger: LuaTrigger::Edit { index: Some(0) }, mode, payload } }

#[test]
fn the_reply_carries_the_batch_result_and_ordered_effects() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let mut host = host();
    let text = |value: &str| Value::Text(Text::from_str(value, &budget).unwrap());
    let mut reply = |code: &str, mode: LuaMode, payload: Value, cancellation: &Cancellation| {
        let access = scope(&store, &pool);
        let triggers = [code.to_owned()];
        answer(&mut host, request(mode, payload), Context { owner: "char-b", triggers: &triggers, access: &access, store: &store,
            cancellation, budget: &budget })
    };
    let output = LuaMode::Script(ScriptMode::EditOutput);
    let cancelled = Cancellation::default();
    cancelled.cancel();
    let appended = reply("listenEdit('editOutput', function(id, value) return value .. '!' end)", output, text("a"), &Cancellation::default());
    assert!(matches!(&appended, Ok(HostReply::Lua(LuaReply { value: Value::Text(value), effects, stop_sending: false })) if value.as_unicode() == Some("a!") && effects.is_empty()), "{appended:?}");
    for ending in ["return value .. '!'", "error('boom')"] {
        let code = format!("listenEdit('editOutput', function(id, value) setChatVar(id, 'k', 'v') setChat(id, 0, 'edited') setChatRole(id, 0, 'narrator') setChatRole(id, 0, 'user') stopChat(id) {ending} end)");
        let written = reply(&code, output, text("a"), &Cancellation::default());
        let Ok(HostReply::Lua(LuaReply { value: Value::Text(value), effects, stop_sending: false })) = written else { panic!("{written:?}") };
        assert_eq!(value.as_unicode(), Some(if ending.starts_with("return") { "a!" } else { "a" }));
        assert!(matches!(effects.as_slice(), [
            Effect::ChatVariable { name, value: Value::Text(value) },
            Effect::Message(MessageEdit::SetData { index, data: Value::Text(data) }),
            Effect::Message(MessageEdit::SetRole { index: role_index, role: MessageRole::Char }),
            Effect::Message(MessageEdit::SetRole { index: user_index, role: MessageRole::User }),
        ] if name.as_unicode() == Some("k") && value.as_unicode() == Some("v") && *index == 0.0
            && data.as_unicode() == Some("edited") && *role_index == 0.0 && *user_index == 0.0), "{effects:?}");
    }
    let declined = reply("listenEdit('editOutput', function(id, value) return cbs('x') end)", output, text("a"), &Cancellation::default());
    assert!(matches!(&declined, Err(failure) if failure.reason == "lua-host:cbs" && failure.edits.is_empty()), "{declined:?}");
    let stopped = reply("listenEdit('editOutput', function(id, value) return value end)", output, text("a"), &cancelled);
    assert!(matches!(stopped, Ok(HostReply::Cancelled)), "{stopped:?}");
    let process = reply("error('never')", LuaMode::Script(ScriptMode::EditProcess), text("kept"), &Cancellation::default());
    assert!(matches!(&process, Ok(HostReply::Lua(LuaReply { value: Value::Text(value), effects, stop_sending: false })) if value.as_unicode() == Some("kept") && effects.is_empty()), "{process:?}");
    let access = scope(&store, &pool);
    let effect = answer(&mut host, HostRequest::Lua { trigger: LuaTrigger::Effect { trigger: 0, effect: 0 }, mode: output, payload: text("a") },
        Context { owner: "char-b", triggers: &[], access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget });
    assert!(matches!(&effect, Ok(HostReply::Unsupported(label)) if label == "lua-trigger"), "{effect:?}");
}

#[test]
fn writes_are_reported_in_call_order_with_the_values_ts_stores() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = scope(&store, &pool);
    let triggers = ["listenEdit('editOutput', function(id, value)
        setChatVar('other', 'refused', '1')
        setChatVar(id, 'k', 'v')
        setChat(id, 0)
        setChatRole(id, 0, 'narrator')
        return value
    end)".to_owned()];
    let outcome = host().run(Batch { owner: "char-b", mode: EditMode::Output, content: Value::Text(Text::from_str("a", &budget).unwrap()),
        index: None, triggers: &triggers, access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).unwrap();
    assert_eq!(outcome.status, Status::Completed);
    assert_eq!(outcome.edits, [Edit::Variable { key: "k".into(), value: "v".into() }, Edit::MessageData { index: 0.0, data: String::new() },
        Edit::MessageRole { index: 0.0, role: "char" }]);
    commit(&access, &store);
    let stored = conversation(&store);
    assert_eq!((&stored["scriptstate"]["$k"], &stored["message"][0]["data"], &stored["message"][0]["role"]), (&json!("v"), &json!(""), &json!("char")));
}

#[test]
fn engines_beyond_the_cache_budget_are_evicted_least_recently_used_first() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let counting = "n = 0 listenEdit('editOutput', function(id, value) n = n + 1 return value .. n end)".to_owned();
    let other = "listenEdit('editOutput', function(id, value) return value end)".to_owned();
    let mut host = host_with(1);
    let mut run = |code: &String| {
        let access = scope(&store, &pool);
        let outcome = host.run(Batch { owner: "char-b", mode: EditMode::Output, content: Value::Text(Text::from_str("a", &budget).unwrap()),
            index: None, triggers: std::slice::from_ref(code), access: &access, store: &store, cancellation: &Cancellation::default(),
            budget: &budget }).unwrap();
        assert_eq!(outcome.status, Status::Completed);
        let Value::Text(text) = outcome.value else { panic!("{:?}", outcome.value) };
        text.as_unicode().unwrap().to_owned()
    };
    let results = [run(&counting), run(&counting), run(&other), run(&counting)];
    assert_eq!(results, ["a1", "a2", "a", "a1"]);
}

fn check_native_failure_keeps_writes(ending: &str, limits: risunest_ir::Limits, reason: &str) {
    let budget = Budget::new(limits, Arc::new(AtomicBool::new(false))).unwrap();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = scope(&store, &pool);
    let triggers = [format!("listenEdit('editOutput', function(id, value) setChatVar(id, 'k', string.rep('v', 65)) setChat(id, 0, 'edited') {ending} end)")];
    let failure = answer(&mut host(), request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("a", &budget).unwrap())),
        Context { owner: "char-b", triggers: &triggers, access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).unwrap_err();
    assert!(failure.reason.starts_with(reason), "{failure:?}");
    assert_eq!(failure.edits, [Edit::Variable { key: "k".into(), value: "v".repeat(65) }, Edit::MessageData { index: 0.0, data: "edited".into() }]);
    commit(&access, &store);
    let stored = conversation(&store);
    assert_eq!(stored["scriptstate"]["$k"], "v".repeat(65));
    assert_eq!(stored["message"][0]["data"], "edited");
}

