#[test]
fn initialization_deadline_keeps_original_data_prior_writes_and_only_completed_engines() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let mut host = EditHost::new(Limits { instructions_per_slice: 1_000, ..Limits::default() }, Duration::from_millis(250), 16).unwrap();
    let triggers = [
        "count = 0 listenEdit('editOutput', function(id, value) count = count + 1 setChatVar(id, 'before', tostring(count)) return value .. count end)".to_owned(),
        "attempt = (attempt or 0) + 1 if attempt == 1 then while true do end end listenEdit('editOutput', function(id, value) return 'reused' end)".to_owned(),
    ];
    for expected in ["1", "2"] {
        let access = scope(&store, &pool);
        let reply = answer(&mut host, request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("original", &budget).unwrap())),
            Context { owner: "char-b", triggers: &triggers, access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).unwrap();
        assert!(matches!(&reply, HostReply::Lua(LuaReply { value: Value::Text(value), effects, stop_sending: false })
            if value.as_unicode() == Some("original") && matches!(effects.as_slice(), [Effect::ChatVariable { name, value: Value::Text(value) }]
                if name.as_unicode() == Some("before") && value.as_unicode() == Some(expected))), "{reply:?}");
        commit(&access, &store);
        assert_eq!(conversation(&store)["scriptstate"]["$before"], expected);
    }
}

#[test]
fn listener_deadline_keeps_writes_and_discards_its_engine() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let mut host = EditHost::new(Limits { instructions_per_slice: 1_000, ..Limits::default() }, Duration::from_millis(250), 16).unwrap();
    let triggers = ["count = 0 listenEdit('editOutput', function(id, value) count = count + 1 setChatVar(id, 'before', tostring(count)) if count == 1 then while true do end end return 'reused' end)".to_owned()];
    for _ in 0..2 {
        let access = scope(&store, &pool);
        let failure = answer(&mut host, request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("original", &budget).unwrap())),
            Context { owner: "char-b", triggers: &triggers, access: &access, store: &store, cancellation: &Cancellation::default(), budget: &budget }).unwrap_err();
        assert_eq!(failure.reason, "lua-edit-timeout");
        assert_eq!(failure.edits, [Edit::Variable { key: "before".into(), value: "1".into() }]);
        commit(&access, &store);
        assert_eq!(conversation(&store)["scriptstate"]["$before"], "1");
    }
}

#[test]
fn cancellation_after_a_write_retains_edits_for_one_settlement() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = Arc::new(AccessPool::new(settings()).unwrap());
    let access = scope(&store, &pool);
    let revision_before = store.borrow().revision().unwrap();
    let stored_before = conversation(&store);
    let cancellation = Cancellation::default();
    let before = pool.used_bytes();
    let observer_pool = pool.clone();
    let observer_cancellation = cancellation.clone();
    // The scope charges the large variable only after staging the write. Wait for that real boundary.
    let observer = std::thread::spawn(move || {
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            if observer_pool.used_bytes() > before + 16_384 {
                observer_cancellation.cancel();
                return true;
            }
            std::thread::yield_now();
        }
        false
    });
    let triggers = ["listenEdit('editOutput', function(id, value) setChatVar(id, 'before', string.rep('v', 32768)) while true do end end)".to_owned()];
    let reply = answer(&mut host(), request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("original", &budget).unwrap())),
        Context { owner: "char-b", triggers: &triggers, access: &access, store: &store, cancellation: &cancellation, budget: &budget });
    assert!(observer.join().unwrap(), "write was not observed before the deadline");
    let failure = reply.unwrap_err();
    assert_eq!(failure.reason, "lua-edit-cancelled");
    assert_eq!(failure.edits, [Edit::Variable { key: "before".into(), value: "v".repeat(32768) }]);
    assert_eq!(store.borrow().revision().unwrap(), revision_before);
    assert_eq!(conversation(&store), stored_before);
    let segment = access.next_segment().unwrap();
    let receipt = access.commit(&mut store.borrow_mut(), &segment, FinishMode::IfChanged).unwrap();
    assert_eq!(receipt.error, None);
    let revision_after = store.borrow().revision().unwrap();
    assert_eq!(revision_after, revision_before + 1);
    assert_eq!(receipt.status, super::access::SegmentStatus::Committed(revision_after));
    assert_eq!(conversation(&store)["scriptstate"]["$before"], "v".repeat(32768));
    let retried = access.commit(&mut store.borrow_mut(), &segment, FinishMode::IfChanged).unwrap();
    assert_eq!(retried, receipt);
    assert_eq!(store.borrow().revision().unwrap(), revision_after);
    assert_eq!(conversation(&store)["scriptstate"]["$before"], "v".repeat(32768));
}
